#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Module with Velocity REST Api client class.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import time
import base64
from six import with_metaclass
import json
import os


from velocity_communicator.core.client_creator import CVelocityClientCreator
from velocity_communicator.core.legacy import CLegacy
from velocity_communicator.support_services.reservation import CReservation
from velocity_communicator.support_services.ci_functions import CIFunctions
from velocity_communicator.support_services.inventory import InventoryServices
from velocity_communicator.support_services.external_services import ExternalServices
from velocity_communicator.core.client_exceptions import AuthenticationError
from velocity_communicator.log.log import Log
from velocity_communicator.rest.query import RestQuery
from velocity_communicator.rest.query import RestQueryException
import velocity_communicator


class VelocityRestClient(with_metaclass(CVelocityClientCreator,
                                        CLegacy,
                                        CReservation,
                                        CIFunctions,
                                        ExternalServices,
                                        InventoryServices)):
    """
        Velocity lab management SW interface\n
        After start URL comes::

            <service type>/<service version>/<command>/<commands>

        Example:
            https://10.35.195.3/velocity/api/topology/v3/folder/{folderID}/topologies

        Arguments:
            base_path (str): Common part of the api call.
            user_id (str): User id in Velocity.
            password (str): User password
            proxy (str/dict): Address of proxy server.
                              Or in dictionary format {'http': '', 'https': ''}
            server (str): Velocity's address
            username (str): User login.
            log_dir(str): Path where log is created. If define log_dir=None, logging to file is disabled
            console_log(str): Is log printed to console. If defined as False logging is disabled
            logger (Logger): Logger object to use for custom logging.

        Keyword arguments:
            token (str): Authentication token.
            token_file (str): Path to txt file containing token string.
            expiration_buffer (int): Time in hours to start warning before token expiration. Default is 7 days.
            warning_interval (int): Minimum time in hours between token expiration warnings. Default is 12 hours.
            overwrite_logs(bool): If True, existing logs will be overwritten (deleted). False by default.
            auth_attempts (int): Number of retries to authenticate before giving up. Default is 5.
            logger_propagate (bool): If True, logger will propagate messages to parent loggers. Default is True.
            basic_auth (str): Username and password as basic authentication.

        Raises:
            AuthenticationError: when script fails to autheticate to velocity.
    """

    def __init__(self, server, username="", password="", proxy=None,
                 log_dir='.', console_log=True, logger=None, **kwargs):
        self.rest_query = RestQuery
        self.username = username
        self.password = password
        self.token = ""
        self.token_expiration_date = 0
        self.real_token_expiration_date = 0
        self.token_auth = kwargs.get('token', "")
        self.token_file = kwargs.get('token_file', "")
        self.expiration_buffer = kwargs.get('expiration_buffer', 168) * 1000 * 60 * 60
        self.warning_interval = kwargs.get('warning_interval', 12) * 3600
        self.overwrite_logs = kwargs.get('overwrite_logs', False)
        self.auth_attempts = kwargs.get('auth_attempts', 5)
        self.logger_propagate = kwargs.get('logger_propagate', True)
        self.basic_auth = kwargs.get('basic_auth', "")
        self.proxy = proxy if proxy else ""
        self.base_path = self._create_base_path(server, 'velocity/')
        self.is_token_auth = False
        self.auth_check = False
        self.last_warning_time = 0
        self.logger = logger if logger is not None else Log.get_logger('velocityclient')
        Log.configure_logging(log_dir,
                              console_log,
                              overwrite=self.overwrite_logs,
                              propagate=self.logger_propagate)

        self.logger.debug(f'Version: {velocity_communicator.__version__}')

        if ((self.username == "" or self.password == "") and
                self.basic_auth == "" and
                self.token_auth == "" and
                self.token_file == ""):
            raise AuthenticationError("Missing Velocity credentials! Give username and password, basic auth key or token!")
        if self.token_auth != "":
            self.is_token_auth = True
            self.token = self.token_auth
            self._authenticate()
        elif self.token_file != "":
            self.read_token_file(self.token_file)

        sensitive_fields = ['password', 'token', 'token_auth', 'basic_auth']
        self.logger.debug(
            f"Initialized REST client with: "
            f"{'; '.join(['{}:{}'.format(k, v) for k, v in vars(self).items() if k not in sensitive_fields])}"
        )

    @staticmethod
    def _create_base_path(server, base_service):
        if not server.endswith('/'):
            server += '/'
        return server + base_service

    def _get_token(self, attempts: int = 10, duration: int = None):
        while attempts >= 0:
            try:
                api_path = 'api/auth/v2/token'
                if duration:
                    api_path += f'?duration={duration}'
                response = self._query(
                    api_path, query_type="get", result=[200],
                    headers={
                        'Authorization': 'Basic ' + self._create_basic_token()
                    }, content_type='application/json'
                )
                return response  # Success, return immediately
            except RestQueryException as ex:
                self.logger.error(f"Could not authorize: {ex}")
                self.logger.warning(f'Attempts left: {attempts}')
                attempts -= 1
                if attempts >= 0:
                    self.logger.warning('Retrying authentication procedure.')
                    time.sleep(30)
        self.logger.warning('Velocity token not received. Authentication failed.')
        return None

    def _is_authentication_required(self):
        """
        Returns True when token has expired, otherwise False
        """
        return True if int(time.time() * 1000) >= int(self.token_expiration_date) else False

    def _authenticate(self, duration: int = None):
        if self.is_token_auth is False:
            response = self._get_token(attempts=self.auth_attempts, duration=duration)
            if not response:
                self.logger.critical('Could not authenticate!')
                raise AuthenticationError(
                    "Failed to authenticate with the Velocity server. Check " +
                    "credentials and Velocity status."
                )
            self.token = response.get('token', None)
            self.token_expiration_date = response.get('expirationDate', 0)
            self.token_expiration_date -= 180000
            response['expirationDate'] = self.token_expiration_date
            self.logger.info("Connected. Velocity authentication token received")
            return response
        elif self.is_token_auth:
            self.token_expiration_date = self.get_token_expiration(self.token)*1000
            self.real_token_expiration_date = self.token_expiration_date

            # Calculate time remaining until REAL expiration
            current_time_ms = time.time() * 1000
            time_remaining_ms = self.real_token_expiration_date - current_time_ms

            hours = int(time_remaining_ms // 1000 // 3600)
            minutes = int((time_remaining_ms // 1000 % 3600) // 60)
            self.logger.info(f'Token expiration: {hours} hours and {minutes} minutes')

            self.token_expiration_date -= self.expiration_buffer
            return {'token': self.token, 'expirationDate': self.token_expiration_date}

    def _create_basic_token(self):
        if self.basic_auth == "":
            if isinstance(self.username, bytes):
                username = self.username
            else:
                username = self.username.encode('utf-8')

            if isinstance(self.password, bytes):
                password = self.password
            else:
                password = self.password.encode('utf-8')
            return base64.b64encode(username + b':' + password).decode('utf-8')
        else:
            return self.basic_auth

    def get_token_expiration(self, token_string):
        """Return expiration date of the token as integer timestamp in seconds."""
        try:
            padding = '=' * (4 - len(token_string) % 4)
            decoded = base64.b64decode(token_string + padding)
            token_data = json.loads(json.loads(decoded.decode('utf-8'))["packet"])
            return token_data["expiration"]
        except (json.JSONDecodeError, KeyError, ValueError, base64.binascii.Error) as e:
            self.logger.error(f"Error parsing token: {e}")
            raise AuthenticationError(f"Invalid token format: {e}")

    def create_token_file(self, json_file: str, duration: int):
        """
        Functionality deprecated because of the change to authentication.
        """
        self.logger.warning("create_token_file method is deprecated! Generate token from Velocity and save it to a file manually if needed.")

    def read_token_file(self, token_file: str):
        """
        Reads a token from a text file containing only the token string.

        Arguments:
            token_file (str): Path to the text file where the token is saved.
        """
        self.is_token_auth = True
        if not os.path.exists(token_file):
            raise FileNotFoundError(f"File {token_file} not found. Can not read token.")

        with open(token_file, 'r') as f_handle:
            token_content = f_handle.read().strip()

        if not token_content:
            raise ValueError(f"Token file {token_file} is empty.")

        self.token = token_content
        self.logger.info(f"Token read from file {token_file}")
        auth_result = self._authenticate()
        print(f'Authentication expiration: {auth_result["expirationDate"]}')
        return {"token": self.token, "expirationDate": auth_result["expirationDate"]}

    def version(self):
        return velocity_communicator.__version__

    def get_server_address(self):
        return self.base_path.split("/velocity/")[0]

    def set_server_address(self, server_address: str, token: str = ""):
        if token == "":
            self.token_expiration_date = 0
            self.token = ""
        else:
            self.token = token
            self.is_token_auth = True
            self.auth_check = False
        self.base_path = self._create_base_path(server_address, "velocity/")
        return self._authenticate()

    def switch_user(self, new_username: str = "", new_password: str = "", token: str = ""):
        if token == "":
            self.username = new_username
            self.password = new_password
            self.token = ""
            self.token_expiration_date = 0
        else:
            self.token = token
            self.is_token_auth = True
            self.auth_check = False
        return self._authenticate()

    def query(self, path_frag, query_type, **kwargs):
        """
        Authentication expiration check before query
        """
        if self._is_authentication_required() and self.is_token_auth:
            current_time = time.time()
            time_remaining = self.real_token_expiration_date/1000 - current_time

            if time_remaining <= 0:
                expired_minutes = int(abs(time_remaining) // 60)
                self.logger.error(f"Token has expired {expired_minutes} minutes ago!")
                raise AuthenticationError(
                    f"Authentication token has expired {expired_minutes} minutes ago. "
                    f"Please generate a new token from Velocity and update your application.")

            time_since_last_warning = current_time - self.last_warning_time
            should_warn = not self.auth_check or time_since_last_warning >= self.warning_interval

            if should_warn:
                self.auth_check = True
                self.last_warning_time = current_time
                try:
                    self.send_token_expiration_warning(time_remaining)
                except Exception as e:
                    self.logger.warning(f"Error to send token expiration warning: {e}")

        elif self._is_authentication_required() and not self.is_token_auth:
            self._authenticate()
        return self._query(path_frag, query_type, **kwargs)

    def _query(self, path_frag, query_type, **kwargs):
        """
            Makes a request using RestQuery class.

            Arguments:
                path_frag (str): A path to append to base path.
                query_type (str): Type of query (get/put/post/delete).

            Keyword Arguments:
                data (str, optional): Body of the request.
                content_type (str, optional): Type of data sent in body.
                accept_type (str, optional): Type of data sent by Velocity.
                result (list, optional): List of expected return codes from
                    Velocity.
                headers (dict, optional): Dict with headers to pass with
                    request.

            Returns:
                str: Response from Velocity as string containing JSON data.
        """
        # Special value, indicating that velocity is under heavy load
        # if 503 not in kwargs["result"]:
        #     kwargs["result"].append(503)
        path = self.base_path + path_frag
        if "ito/" in path:
            path = path.replace('velocity/', '')
        query = self.rest_query(
            path, query_type, auth_token=self.token,
            proxies=self.proxy, **kwargs
        )
        response = query.request()
        return response


if __name__ == "__main__":
    pass
